// MyFinZen — textos de ayuda (icono "i" de cada sección) y manual de usuario, en español e inglés.
// HELP[clave] = {es:{t, d:[párrafos], steps:[pasos]}, en:{...}}. Las claves se usan con helpBtn('clave') en index.html.
// HELP_GROUPS ordena las ayudas por pantalla para el manual. MANUAL tiene los capítulos generales.
// Si añades una sección nueva a la app, añade aquí su ayuda en los dos idiomas.
'use strict';
window.HELP = {
  /* ---------- Resumen ---------- */
  stat_nw: {
    es: { t: 'Patrimonio neto', d: ['Lo que tienes menos lo que debes: bancos, inversiones, jubilación e inmuebles, menos tarjetas e hipotecas. Usa el último saldo conocido de cada cuenta.'],
      steps: ['Añade todas tus cuentas en <b>Cuentas</b>, también la casa (con su valor estimado) y las hipotecas.', 'Actualiza los saldos cada mes, a mano o importando los extractos.', 'Si una cuenta lleva más de 40 días sin saldo, aparece un aviso en el Resumen.'] },
    en: { t: 'Net worth', d: ['What you own minus what you owe: banks, investments, retirement and property, minus cards and mortgages. It uses the latest known balance of each account.'],
      steps: ['Add all your accounts in <b>Accounts</b>, including the house (with its estimated value) and the mortgages.', 'Update balances every month, by hand or by importing statements.', 'If an account has had no balance for more than 40 days, an alert appears on the Overview.'] } },
  stat_cash: {
    es: { t: 'Efectivo', d: ['Suma de tus cuentas de banco y ahorro: el dinero disponible ya. Debajo ves lo que debes en tarjetas.', 'Es la base del fondo de emergencia: la app compara esta cifra con tus gastos medios.'], steps: ['Marca como "Banco / ahorro" las cuentas corrientes y de ahorro.', 'Elige cuántos meses quieres cubrir en <b>Copia y ajustes → Preferencias</b>.'] },
    en: { t: 'Cash', d: ['Sum of your bank and savings accounts: money available right now. Below it you see what you owe on cards.', 'It is the basis of the emergency fund: the app compares this figure with your average spending.'], steps: ['Mark checking and savings accounts as "Bank / savings".', 'Choose how many months to cover in <b>Backup & settings → Preferences</b>.'] } },
  stat_mort: {
    es: { t: 'Hipotecas', d: ['Lo que debes en total en tus hipotecas y la cuota mensual que pagas por todas (capital, intereses, escrow y principal extra).'], steps: ['Importa el último extracto de cada hipoteca: la app actualiza el saldo y la cuota.', 'El detalle y el simulador de pagos extra están en <b>Hipotecas</b>.'] },
    en: { t: 'Mortgages', d: ['What you owe in total on your mortgages and the monthly payment for all of them (principal, interest, escrow and extra principal).'], steps: ['Import each mortgage\'s latest statement: the app updates the balance and the payment.', 'The detail and the extra-payment simulator are in <b>Mortgages</b>.'] } },
  onboard: {
    es: { t: 'Primeros pasos', d: ['Tres pasos para empezar con buen pie. Se marcan solos a medida que los haces y la tarjeta desaparece al terminar.'], steps: ['La contraseña y la clave de recuperación ya están: guárdala en papel.', 'Importa un extracto de cada cuenta en <b>Cuentas</b>: la app crea las cuentas a partir de los documentos.', 'Haz una copia cifrada en <b>Copia y ajustes</b> y guárdala fuera del móvil.', '"Ocultar" quita la tarjeta aunque no hayas terminado.'] },
    en: { t: 'Getting started', d: ['Three steps to get off on the right foot. They tick themselves off as you do them, and the card disappears when you finish.'], steps: ['The password and recovery key are done: keep the key on paper.', 'Import a statement for each account in <b>Accounts</b>: the app creates the accounts from the documents.', 'Make an encrypted backup in <b>Backup & settings</b> and keep it off your phone.', '"Hide" removes the card even if you haven\'t finished.'] } },
  month_sum: {
    es: { t: 'Resumen del mes', d: ['Lo que entró, lo que salió y lo que ahorraste en el mes elegido (o en el último con datos). No cuenta transferencias entre tus cuentas ni pagos de tarjeta; las hipotecas cuentan como cuota fija.'], steps: ['Elige otro mes en el filtro de arriba para verlo.'] },
    en: { t: 'Month summary', d: ['What came in, what went out and what you saved in the chosen month (or the latest one with data). Transfers between your accounts and card payments are not counted; mortgages count as a fixed payment.'], steps: ['Pick another month in the filter above to see it.'] } },
  stat_inv: {
    es: { t: 'Inversiones y jubilación', d: ['Suma de las cuentas de inversión, jubilación (401(k), IRA) y ahorro de los hijos.'], steps: ['Actualiza su saldo cada mes en <b>Inversiones</b> o importa el extracto en PDF.', 'Para ver posiciones, importa el CSV de Holdings de M1.'] },
    en: { t: 'Investments & retirement', d: ['Sum of brokerage, retirement (401(k), IRA) and kids savings accounts.'], steps: ['Update the balance every month in <b>Investments</b> or import the PDF statement.', 'To see positions, import the M1 Holdings CSV.'] } },
  stat_save: {
    es: { t: 'Ahorro del mes', d: ['Ingresos menos gastos del último mes completo. No cuenta transferencias entre tus cuentas, pagos de tarjeta ni aportaciones a inversión, y las hipotecas cuentan como cuota fija mensual.'], steps: ['Importa los movimientos de todos tus bancos y tarjetas para que la cifra sea real.', 'Revisa las categorías en <b>Movimientos</b>.'] },
    en: { t: 'Savings this month', d: ['Income minus expenses for the last complete month. Transfers between your accounts, card payments and investment contributions are not counted, and mortgages count as a fixed monthly payment.'], steps: ['Import transactions from all your banks and cards so the figure is real.', 'Review the categories in <b>Transactions</b>.'] } },
  alerts: {
    es: { t: 'Avisos', d: ['La app revisa tus datos y te avisa de lo importante: copias de seguridad, saldos antiguos, diferencias entre cuentas, meses con más gasto que ingreso, categorías que suben, fondo de emergencia, deuda de tarjeta y la rentabilidad del alquiler.', 'Verde = va bien; amarillo = conviene revisarlo; rojo = urgente; azul = información.'], steps: ['Toca la línea de avisos para abrirla y toca un aviso para ir directamente a donde tienes que decidir o actuar (por ejemplo, los movimientos sin categoría o la conciliación).', 'La <b>×</b> ignora un aviso. Si la situación cambia (otro mes, otra cantidad), vuelve a aparecer. "Volver a mostrar" recupera los que ignoraste.', 'Los de conciliación se resuelven en <b>Movimientos → Conciliación entre cuentas</b>.'] },
    en: { t: 'Alerts', d: ['The app checks your data and flags what matters: backups, old balances, differences between accounts, months with more spending than income, rising categories, emergency fund, card debt and rental profitability.', 'Green = fine; yellow = worth checking; red = urgent; blue = information.'], steps: ['Tap the alerts line to open it, and tap an alert to go straight to where you need to decide or act (for example, uncategorized transactions or the reconciliation).', 'The <b>×</b> ignores an alert. If the situation changes (another month, another amount), it comes back. "Show again" restores the ones you ignored.', 'Reconciliation alerts are resolved in <b>Transactions → Reconciliation between accounts</b>.'] } },
  nw_chart: {
    es: { t: 'Evolución del patrimonio', d: ['Patrimonio neto, activos y deudas a fin de cada mes de los últimos 12, con el último saldo conocido de cada cuenta en esa fecha.'], steps: ['Pasa el dedo o el ratón por el gráfico para ver las cifras de cada mes.', 'Cuantos más saldos históricos tengas (extractos antiguos), más fiel será la curva.'] },
    en: { t: 'Net worth over time', d: ['Net worth, assets and debts at the end of each of the last 12 months, using the latest balance of each account on that date.'], steps: ['Move your finger or mouse over the chart to see each month.', 'The more historical balances you have (old statements), the more accurate the curve.'] } },
  mix: {
    es: { t: 'Dónde está tu dinero', d: ['Saldo actual por tipo de cuenta. Las deudas (tarjetas, hipotecas) aparecen marcadas como deuda.'], steps: ['Usa esta vista para ver de un vistazo cuánto tienes líquido, invertido y en inmuebles.'] },
    en: { t: 'Where your money is', d: ['Current balance by account type. Debts (cards, mortgages) are marked as debt.'], steps: ['Use this view to see at a glance how much is in cash, invested and in property.'] } },

  /* ---------- Movimientos ---------- */
  cf_chart: {
    es: { t: 'Ingresos, gastos y ahorro', d: ['Barras por mes de los últimos 12: lo que entró, lo que salió y la diferencia.', 'No cuentan las transferencias entre tus cuentas, los pagos de tarjeta (ya cuentan las compras de la tarjeta) ni las aportaciones a inversión. Cada hipoteca cuenta como su cuota fija mensual (cuota + escrow + extra) todos los meses, aunque un mes haya dos cargos o ninguno.'], steps: ['Importa los movimientos del banco y de las tarjetas del mismo periodo.', 'Pasa el dedo por las barras para ver las cifras.'] },
    en: { t: 'Income, expenses and savings', d: ['Bars for each of the last 12 months: what came in, what went out and the difference.', 'Transfers between your accounts, card payments (the card purchases already count) and investment contributions are not counted. Each mortgage counts as its fixed monthly payment (payment + escrow + extra) every month, even if a month has two debits or none.'], steps: ['Import bank and card transactions for the same period.', 'Move your finger over the bars to see the figures.'] } },
  cat_chart: {
    es: { t: 'Gasto por categoría', d: ['Cuánto gastas en cada categoría: media mensual de los últimos 12 meses, o el total del mes que elijas en el filtro. Arriba, lo que entró, lo que salió y lo que ahorraste en ese mes (o en el último con datos).', 'No cuenta transferencias entre tus cuentas ni pagos de tarjeta; las hipotecas cuentan como cuota fija.', 'Cada banco y tarjeta tiene movimientos hasta la fecha de su último extracto. Si alguno no llega al final del mes, el ahorro sale como provisional y te dice qué falta. Si tu nómina es regular y el extracto del banco aún no la trae, se cuenta una nómina estimada (importe y día habituales) hasta que llegue la real.', 'Para tener el dato exacto antes, descarga en la web del banco la actividad reciente en CSV e impórtala: cuando llegue el extracto en PDF, sustituye esos movimientos sin duplicarlos.'], steps: ['Elige un mes en el filtro de arriba para ver solo ese mes.', 'Si hay movimientos sin categoría, revísalos para que el gráfico sea útil.'] },
    en: { t: 'Spending by category', d: ['How much you spend in each category: monthly average over the last 12 months, or the total for the month you pick in the filter. At the top, what came in, what went out and what you saved that month (or the latest one with data).', 'Transfers between your accounts and card payments are not counted; mortgages count as a fixed payment.', 'Each bank and card has transactions up to the date of its last statement. If any of them does not reach the end of the month, the savings are shown as provisional and the app tells you what is missing. If your paycheck is regular and the bank statement does not include it yet, an estimated paycheck (usual amount and day) is counted until the real one arrives.', 'To get the exact figure sooner, download the recent activity as CSV from your bank\'s website and import it: when the PDF statement arrives, it replaces those transactions without duplicates.'], steps: ['Pick a month in the filter above to see only that month.', 'If there are uncategorized transactions, review them so the chart is useful.'] } },
  add_tx: {
    es: { t: 'Añadir movimiento', d: ['Para gastos en efectivo o cualquier cosa que no aparezca en tus extractos. Se abre con el botón <b>+</b> de abajo a la derecha.'], steps: ['Pon la fecha, el importe (negativo si es un gasto; si eliges una categoría de gasto y pones un número positivo, se convierte en negativo) y una descripción.', 'Elige la categoría o crea una nueva con "+ Nueva categoría…".', 'La cuenta es opcional.'] },
    en: { t: 'Add a transaction', d: ['For cash spending or anything that doesn\'t appear in your statements. It opens from the <b>+</b> button at the bottom right.'], steps: ['Enter the date, the amount (negative for an expense; if you pick an expense category and type a positive number, it becomes negative) and a description.', 'Choose the category or create a new one with "+ New category…".', 'The account is optional.'] } },
  rec: {
    es: { t: 'Conciliación entre cuentas', d: ['Compara tus cuentas entre sí para que el gasto no se cuente dos veces y para detectar errores:',
      '• <b>Pagos de tarjeta</b>: el cargo en el banco se empareja con el "payment" de la tarjeta (mismo importe, pocos días de diferencia). Ninguno de los dos cuenta como gasto; cuentan las compras de la tarjeta.<br>• <b>Transferencias</b> entre tus cuentas: no son gasto ni ingreso.<br>• <b>Cuotas de hipoteca</b>: el cargo del banco se asigna a su hipoteca por el importe del extracto (cuota + escrow + extra), así distingue la casa del alquiler aunque sean de la misma entidad.',
      'También avisa de: pagos a tarjetas cuyos movimientos no has importado, cuotas que faltan o no coinciden con el extracto, saldo de la hipoteca que no cuadra entre extractos, saldo de banco o tarjeta que no cuadra con sus movimientos, y posibles duplicados entre CSV y PDF.'],
      steps: ['Importa el banco y las tarjetas del mismo periodo, y el último extracto de cada hipoteca.', 'Lee cada aviso: si es un duplicado, bórralo con su botón; si es correcto, pulsa "Ignorar".', 'Si cambias a mano la categoría de un movimiento emparejado, la app respeta tu elección.'] },
    en: { t: 'Reconciliation between accounts', d: ['Compares your accounts with each other so spending is not counted twice and to catch mistakes:',
      '• <b>Card payments</b>: the bank debit is matched with the card\'s "payment" (same amount, a few days apart). Neither counts as spending; the card purchases do.<br>• <b>Transfers</b> between your accounts: neither spending nor income.<br>• <b>Mortgage payments</b>: the bank debit is assigned to its mortgage by the statement amount (payment + escrow + extra), so it tells the home from the rental even with the same lender.',
      'It also warns about: payments to cards whose transactions you haven\'t imported, missing payments or payments that don\'t match the statement, a mortgage balance that doesn\'t add up between statements, a bank or card balance that doesn\'t match its transactions, and possible CSV/PDF duplicates.'],
      steps: ['Import bank and card data for the same period, and the latest statement of each mortgage.', 'Read each alert: if it is a duplicate, delete it with its button; if it is fine, tap "Ignore".', 'If you change the category of a matched transaction by hand, the app respects your choice.'] } },
  tx_list: {
    es: { t: 'Movimientos', d: ['Todos tus movimientos importados o añadidos a mano. Los que están emparejados con otra cuenta muestran "↔" y la cuenta con la que cuadran.', 'Lo que la app no sabe clasificar con seguridad queda como <b>Sin categoría</b> (en amarillo, con aviso). No es lo mismo que «Otros gastos» u «Otros ingresos»: esas son categorías que eliges tú cuando algo no encaja en ninguna. Para resolver un movimiento sin categoría, tócalo y elige cualquier categoría, incluida «Otros»; sin categoría cuenta como gasto o ingreso según su signo.'], steps: ['Están agrupados por día, del más reciente al más antiguo. Filtra por mes, por categoría o busca por texto.', 'Con "Ordenar por" los ves por fecha (más reciente o más antigua primero) o por importe (de mayor a menor o al revés). Ordenados por importe, cada movimiento muestra su fecha.', 'La categoría se pone sola por el comercio (palabras completas, sin tener en cuenta tu nombre ni los números de referencia). Si la app no está segura, lo deja en amarillo como <b>Sin categoría</b> y te avisa: toca el aviso o elige "Sin categoría (por revisar)" en el filtro.', 'Toca un movimiento para cambiar su categoría: la app te ofrece crear una regla para aplicarla a todos los movimientos parecidos, también a los que importes en el futuro. Desde ahí también lo puedes borrar.', 'Con "Categorías" creas, renombras o borras tus propias categorías.'] },
    en: { t: 'Transactions', d: ['All your imported or hand-entered transactions. Those matched with another account show "↔" and the account they match.', 'Anything the app can\'t classify with confidence stays <b>Uncategorized</b> (in yellow, with an alert). It isn\'t the same as "Other expenses" or "Other income": those are categories you choose when something fits nowhere else. To resolve an uncategorized transaction, tap it and choose any category, including "Other"; while uncategorized it counts as an expense or income depending on its sign.'], steps: ['They are grouped by day, newest first. Filter by month, by category or search by text.', 'With "Sort by" you see them by date (newest or oldest first) or by amount (largest or smallest first). Sorted by amount, each transaction shows its date.', 'The category is set automatically from the merchant (whole words, ignoring your name and reference numbers). If the app isn\'t sure, it leaves it in yellow as <b>Uncategorized</b> and alerts you: tap the alert or pick "Uncategorized (to review)" in the filter.', 'Tap a transaction to change its category: the app offers to create a rule to apply it to all similar transactions, including future imports. You can also delete it from there.', 'With "Categories" you create, rename or delete your own categories.'] } },
  categories: {
    es: { t: 'Categorías propias', d: ['Además de las categorías de sistema puedes crear las tuyas (por ejemplo "Mascotas" o "Gimnasio"). Cada una es de tipo gasto, ingreso o neutra; las neutras no cuentan en el ahorro.', 'Las categorías de sistema no se pueden borrar porque la app las usa para la hipoteca, el alquiler, los impuestos y la conciliación.'], steps: ['Crea una desde el desplegable de cualquier movimiento ("+ Nueva categoría…") o desde <b>Movimientos → Categorías…</b>.', 'Para renombrarla, edita su nombre en la lista: se actualizan sus movimientos y reglas.', 'Al borrarla, sus movimientos pasan a "Otros gastos", "Otros ingresos" o "Transferencia" según su tipo.'] },
    en: { t: 'Custom categories', d: ['Besides the system categories you can create your own (for example "Pets" or "Gym"). Each is an expense, income or neutral type; neutral ones don\'t count toward savings.', 'System categories can\'t be deleted because the app relies on them for the mortgage, rental, taxes and reconciliation.'], steps: ['Create one from any transaction\'s dropdown ("+ New category…") or from <b>Transactions → Categories…</b>.', 'To rename it, edit its name in the list: its transactions and rules are updated.', 'When you delete it, its transactions move to "Other expenses", "Other income" or "Transfer" depending on its type.'] } },

  /* ---------- Hipotecas ---------- */
  mortgage: {
    es: { t: 'Hipoteca', d: ['Saldo pendiente, tipo, cuota (capital + intereses), principal extra y escrow, con la fecha en que terminarás de pagarla y los intereses que te quedan.', 'Cada hipoteca va unida a su inmueble (vivienda habitual o alquiler): al importar el extracto te pregunta de qué casa es o la crea, y así ves el capital propio y los impuestos usan el inmueble correcto. Puedes cambiarlo con "Cambiar". Si borras el inmueble, se borra también su hipoteca.', 'En tus gastos cuenta como una cuota fija mensual (cuota + escrow + extra). Debajo ves el último pago encontrado en tus cuentas de banco y si coincide con el extracto.'], steps: ['Importa el PDF del extracto (Pennymac se lee automáticamente) o añádela a mano.', 'Si es la hipoteca de la casa alquilada, vincúlala al inmueble: así cuenta como "Hipoteca alquiler" y entra en el Schedule E.', 'Importa cada extracto nuevo: la app comprueba que el saldo baja lo que debe.'] },
    en: { t: 'Mortgage', d: ['Outstanding balance, rate, payment (principal + interest), extra principal and escrow, with your payoff date and remaining interest.', 'Every mortgage is linked to its property (home or rental): when you import the statement it asks which home it is for or creates it, so you see your equity and taxes use the right property. You can change it with "Change". If you delete the property, its mortgage is deleted too.', 'In your expenses it counts as a fixed monthly payment (payment + escrow + extra). Below you see the last payment found in your bank accounts and whether it matches the statement.'], steps: ['Import the statement PDF (Pennymac is read automatically) or add it by hand.', 'If it is the rental\'s mortgage, link it to the property: it then counts as "Rental mortgage" and goes into Schedule E.', 'Import each new statement: the app checks the balance drops as it should.'] } },
  mort_sim: {
    es: { t: 'Simulador de pago extra', d: ['Mueve el control para ver qué pasaría si pagaras otra cantidad de principal extra cada mes: cuándo terminarías y cuántos intereses ahorrarías frente a tu extra actual.', 'No cambia tus datos: es solo una simulación. Antes de pagar más, piensa en tu fondo de emergencia y en otras deudas o inversiones.'], steps: ['Desliza el control.', 'Compara las tres líneas del gráfico: sin extra, tu extra actual y el simulado.'] },
    en: { t: 'Extra payment simulator', d: ['Move the slider to see what would happen if you paid a different amount of extra principal every month: when you would finish and how much interest you would save compared with your current extra.', 'It doesn\'t change your data: it is only a simulation. Before paying more, think about your emergency fund and other debts or investments.'], steps: ['Drag the slider.', 'Compare the three lines on the chart: no extra, your current extra and the simulated one.'] } },

  mortcalc: {
    es: { t: 'Calculadora de hipoteca', d: ['Calcula la cuota mensual de una hipoteca nueva o de un refinanciamiento: capital e intereses, impuesto de propiedad, seguro, HOA y, si das menos del 20% de entrada, el seguro hipotecario (PMI). También te dice si el préstamo es conforme, conforme de importe alto o jumbo según el límite de tu condado.', 'Si no escribes un tipo, usa el de hoy para tu crédito, tu entrada y el tipo de préstamo (ver "Tipos de hipoteca hoy").'], steps: ['Pon el precio y la entrada; el préstamo es la diferencia.', 'Elige el plazo, tu puntuación de crédito (FICO) y el límite de tu condado (Orange y Los Ángeles son de alto coste).', 'Ajusta el impuesto de propiedad (en California, alrededor del 1% del precio más los impuestos locales), el seguro y la HOA.', 'Escribe un tipo si ya tienes una oferta; bórralo para volver al de hoy. Se guarda lo último que pusiste.'] },
    en: { t: 'Mortgage calculator', d: ['Works out the monthly payment for a new mortgage or a refinance: principal and interest, property tax, insurance, HOA and, if you put down less than 20%, mortgage insurance (PMI). It also tells you whether the loan is conforming, high-balance conforming or jumbo based on your county\'s limit.', 'If you don\'t enter a rate, it uses today\'s rate for your credit, down payment and loan type (see "Mortgage rates today").'], steps: ['Enter the price and the down payment; the loan is the difference.', 'Choose the term, your credit score (FICO) and your county\'s limit (Orange and Los Angeles are high cost).', 'Adjust property tax (in California, about 1% of the price plus local taxes), insurance and HOA.', 'Enter a rate if you already have an offer; clear it to go back to today\'s. What you entered last is saved.'] } },
  mortrates: {
    es: { t: 'Tipos de hipoteca hoy', d: ['Tipos medios actuales de las hipotecas en EE. UU., que en California van muy parejos: a 30 años según tu puntuación de crédito (FICO) y tu entrada, y también a 15 años, jumbo, FHA y VA. La flecha indica cuánto han cambiado en 4 semanas.', 'Vienen de FRED (Banco de la Reserva Federal de St. Louis): los índices de Optimal Blue, que son la media de los tipos bloqueados de verdad cada día, y la encuesta semanal de Freddie Mac. Se actualizan cada día; tu tipo final dependerá del prestamista, los puntos y tu situación.', 'Según la cantidad del préstamo: hasta el límite conforme es un préstamo conforme; en condados de alto coste como Orange hay un límite más alto (high-balance); por encima, jumbo.'], steps: ['Busca tu fila de FICO y la columna de tu entrada.', 'En "Tus hipotecas frente a hoy" ves si refinanciar podría compensar.', 'Úsalo como referencia y pide ofertas a varios prestamistas antes de decidir.'] },
    en: { t: 'Mortgage rates today', d: ['Current average mortgage rates in the US, which California tracks closely: 30-year by credit score (FICO) and down payment, plus 15-year, jumbo, FHA and VA. The arrow shows how much they changed in 4 weeks.', 'They come from FRED (Federal Reserve Bank of St. Louis): the Optimal Blue indices, which average the rates actually locked each day, and Freddie Mac\'s weekly survey. They are updated daily; your final rate will depend on the lender, the points and your situation.', 'By loan amount: up to the conforming limit it\'s a conforming loan; high-cost counties such as Orange have a higher limit (high-balance); above that, jumbo.'], steps: ['Find your FICO row and your down-payment column.', 'In "Your mortgages vs. today" you can see whether refinancing could pay off.', 'Use it as a reference and get quotes from several lenders before deciding.'] } },

  /* ---------- Inversiones ---------- */
  inv_total: {
    es: { t: 'Total invertido', d: ['Suma de tus cuentas de inversión, jubilación y de los niños, con el reparto por tipo. Si indicas lo que has aportado, verás la ganancia.'], steps: ['Edita cada cuenta en <b>Cuentas</b> y pon el "Total aportado", o deja que se rellene con el coste del CSV de Holdings.'] },
    en: { t: 'Total invested', d: ['Sum of your brokerage, retirement and kids accounts, with the split by type. If you enter what you contributed, you\'ll see the gain.'], steps: ['Edit each account in <b>Accounts</b> and set "Total contributed", or let the Holdings CSV cost fill it in.'] } },
  inv_chart: {
    es: { t: 'Evolución de tus inversiones', d: ['Saldo a fin de cada mes de cada cuenta de inversión. Incluye tus aportaciones, así que no es solo rentabilidad.'], steps: ['Actualiza los saldos cada mes con "Actualizar saldo" o importando el extracto.'] },
    en: { t: 'How your investments evolve', d: ['Month-end balance of each investment account. It includes your contributions, so it is not just returns.'], steps: ['Update balances every month with "Update balance" or by importing the statement.'] } },
  retire: {
    es: { t: 'Tu jubilación', d: ['Estimación de cuánto tendrías al jubilarte con tus cuentas de jubilación (401(k), IRA) y cuánto podrías gastar al mes. Todo en <b>dólares de hoy</b>: la rentabilidad ya descuenta la inflación.', 'Cada año el saldo crece con la rentabilidad y suma tu aportación (la tuya y la de la empresa, leída del último extracto). El ingreso mensual usa la <b>regla del 4%</b>: retirar el 4% del saldo el primer año y luego ajustarlo por inflación suele aguantar 30 años. Si pones tu Seguridad Social estimada a los 67 (en ssa.gov, "my Social Security"), se ajusta según la edad a la que la pidas (62 = 70%, 70 = 124%).'], steps: ['Pon tu año de nacimiento y mueve la edad de jubilación para ver cómo cambia.', 'Ajusta la rentabilidad real: 4–6% es razonable para una cartera mayoritariamente en acciones a largo plazo; 2–3% si es conservadora.', 'Opcional: pon el ingreso mensual que quieres y verás cuánto más tendrías que aportar al año.', 'La tabla compara jubilarte a los 55, 60, 62, 65, 67 y 70.', 'Es una estimación orientativa, antes de impuestos; no sustituye a un asesor financiero.'] },
    en: { t: 'Your retirement', d: ['An estimate of how much you\'d have when you retire with your retirement accounts (401(k), IRA) and how much you could spend each month. All in <b>today\'s dollars</b>: the return is already net of inflation.', 'Each year the balance grows by the return and adds your contribution (yours and your employer\'s, read from the latest statement). The monthly income uses the <b>4% rule</b>: withdrawing 4% of the balance the first year and then adjusting for inflation usually lasts 30 years. If you enter your estimated Social Security at 67 (on ssa.gov, "my Social Security"), it\'s adjusted for the age you claim it (62 = 70%, 70 = 124%).'], steps: ['Enter your birth year and move the retirement age to see how it changes.', 'Adjust the real return: 4–6% is reasonable for a mostly-stock long-term portfolio; 2–3% if it\'s conservative.', 'Optional: enter the monthly income you want and you\'ll see how much more you\'d need to contribute each year.', 'The table compares retiring at 55, 60, 62, 65, 67 and 70.', 'It\'s a rough estimate, before taxes; it is not a substitute for a financial advisor.'] } },
  retire_tips: {
    es: { t: 'Recomendaciones para tu 401(k)', d: ['Reglas generales a partir de tus datos: cuánto aportas frente al máximo legal del año (con la aportación adicional a partir de 50 y de 60 a 63), la aportación de la empresa, el reparto entre acciones y bonos frente al de un fondo de fecha objetivo para tus años hasta la jubilación, la parte internacional, los fondos de gestión activa (más caros) y los que se solapan.', 'Si tienes la declaración en <b>Impuestos</b>, también compara tradicional y Roth según tu tipo marginal.'], steps: ['Los cambios de aportación o de fondos se hacen en la web de tu plan (por ejemplo, Empower).', 'En un 401(k), cambiar de fondo no paga impuestos.', 'Revisa el "expense ratio" de cada fondo en la web del plan antes de decidir.', 'Son orientaciones educativas, no asesoramiento financiero.'] },
    en: { t: 'Recommendations for your 401(k)', d: ['General rules based on your data: how much you contribute versus the year\'s legal maximum (with the extra catch-up from 50 and from 60 to 63), the employer contribution, the stock/bond split versus a target-date fund for your years to retirement, the international share, actively managed (more expensive) funds and overlapping ones.', 'If your return is in <b>Taxes</b>, it also compares traditional and Roth by your marginal rate.'], steps: ['Contribution or fund changes are made on your plan\'s website (for example, Empower).', 'In a 401(k), switching funds doesn\'t trigger taxes.', 'Check each fund\'s expense ratio on the plan\'s website before deciding.', 'This is educational guidance, not financial advice.'] } },
  retire_nofunds: {
    es: { t: 'Fondos del 401(k)', d: ['Los fondos se leen del extracto trimestral en PDF (tabla "How is my account invested?"). Si importaste el extracto antes de que la app supiera leerla, solo se guardó el saldo.'], steps: ['Pulsa "Importar extracto" y elige el último extracto trimestral de esta cuenta.', 'Verás su distribución por tipo de activo, igual que en las demás cuentas.'] },
    en: { t: '401(k) funds', d: ['The funds are read from the quarterly PDF statement (the "How is my account invested?" table). If you imported the statement before the app could read it, only the balance was saved.'], steps: ['Tap "Import statement" and choose this account\'s latest quarterly statement.', 'You\'ll see its breakdown by asset class, like the other accounts.'] } },
  holdings: {
    es: { t: 'Posiciones', d: ['Lo que tienes dentro de la cuenta: reparto por tipo de activo, concentración, acciones individuales y candidatas a vender con pérdida para ahorrar impuestos (tax-loss harvesting).', 'En un 401(k) o una IRA verás los <b>fondos</b> del plan con su tipo (EE. UU. grandes, medianas, internacional, bonos…) y el reparto entre acciones y bonos; ahí cambiar de fondo no paga impuestos.'], steps: ['En M1, descarga el CSV de Holdings de la cuenta. Para el 401(k), basta con importar el extracto trimestral en PDF (Empower): la app lee la tabla de fondos y comprueba que suma el total.', 'Súbelo en <b>Cuentas → Importar</b> (o pégalo como texto) y elige la cuenta.', 'Repítelo de vez en cuando para tener las cifras al día.'] },
    en: { t: 'Positions', d: ['What is inside the account: split by asset class, concentration, individual stocks and candidates to sell at a loss to save taxes (tax-loss harvesting).', 'In a 401(k) or an IRA you\'ll see the plan\'s <b>funds</b> with their type (US large cap, mid cap, international, bonds…) and the split between stocks and bonds; switching funds there doesn\'t trigger taxes.'], steps: ['In M1, download the account\'s Holdings CSV. For the 401(k), just import the quarterly PDF statement (Empower): the app reads the fund table and checks that it adds up to the total.', 'Upload it in <b>Accounts → Import</b> (or paste it as text) and choose the account.', 'Repeat now and then to keep the figures current.'] } },

  news: {
    es: { t: 'Noticias', d: ['Titulares financieros actualizados cada hora y agrupados por día: tu cartera, global, EE. UU., Europa, España y los países que elijas. Los enlaces llevan a la web que publica cada noticia.', '<b>Solo medios contrastados y gratuitos</b>: agencias (AP, EFE, Europa Press…), radiotelevisiones públicas (NPR, RTVE, DW…) y redacciones reconocidas de acceso libre. Se descartan los medios con muro de pago (también los que cobran tras unos artículos, como CNN o la BBC en EE. UU.), los agregadores con contenido patrocinado, la opinión y las listas de "acciones para comprar". La lista es pública, en <code>news/sources.json</code>.', '<b>Alto impacto</b> marca las noticias de política monetaria, inflación, empleo, aranceles o crisis, y las que publican varios medios. <b>N medios</b> dice cuántos medios distintos cuentan la misma noticia ("También en" enlaza a los demás). Las de menor impacto quedan plegadas al final de cada pestaña.', '<b>Aprende de ti</b>: al volver de leer una noticia te pregunta si te ha resultado relevante. Con tus respuestas (tema, medio, región, empresas y palabras del titular) ordena cada día lo que más te interesa primero ("Para ti") y pliega lo que no. Se guarda cifrado en el dispositivo; en "Lo que ha aprendido" lo ves y lo puedes olvidar.', 'Cada noticia lleva el logo (iniciales) del medio, su <b>tema</b> (Empresas, Mercados, Economía, Política, Tecnología, Energía, Cripto, Vivienda, Impuestos o Finanzas) y su <b>origen</b> con bandera (Global, EE. UU., California, Europa, España…). La app los deduce del titular y de la región de la fuente.', 'Para la pestaña "Mi cartera", la app descarga la misma lista pública que cualquiera y la filtra en tu dispositivo con tus posiciones: nadie sabe qué tienes.'],
      steps: ['Importa el CSV de Holdings de M1 para ver las noticias de tus posiciones; toca un símbolo para ver solo las suyas.', 'Abre una noticia; al volver, responde "Sí, relevante" o "No me interesa". "Para ti" ordena por lo que te importa; "Recientes", por hora.', 'Cambia de pestaña con los botones o con las teclas 1–6; "/" busca y "R" actualiza.', 'Toca un tema (Economía, Política…) para ver solo esas noticias.', 'En "Países" elige los que te interesan; se recuerdan.', 'La × de un titular oculta esa fuente; la recuperas en "Estado de las fuentes".'] },
    en: { t: 'News', d: ['Financial headlines refreshed every hour and grouped by day: your portfolio, global, US, Europe, Spain and the countries you choose. The links go to the website that publishes each story.', '<b>Only established, free outlets</b>: news agencies (AP, EFE, Europa Press…), public broadcasters (NPR, RTVE, DW…) and recognized free-access newsrooms. Outlets with a paywall (including those that charge after a few articles, like CNN or the BBC in the US), aggregators with sponsored content, opinion pieces and "stocks to buy" lists are left out. The list is public, in <code>news/sources.json</code>.', '<b>High impact</b> marks news on monetary policy, inflation, jobs, tariffs or crises, and stories reported by several outlets. <b>N outlets</b> says how many different outlets report the same story ("Also in" links to the others). Lower-impact stories are folded at the end of each tab.', '<b>It learns from you</b>: when you come back from reading a story it asks whether it was relevant. With your answers (topic, outlet, region, companies and headline words) it puts what interests you most first each day ("For you") and folds what doesn\'t. It is saved encrypted on the device; "What it has learned" shows it and lets you forget it.', 'Each story shows the outlet\'s logo (initials), its <b>topic</b> (Companies, Markets, Economy, Politics, Tech, Energy, Crypto, Housing, Taxes or Finance) and its <b>origin</b> with a flag (Global, US, California, Europe, Spain…). The app works them out from the headline and the source\'s region.', 'For the "My portfolio" tab, the app downloads the same public list as everyone else and filters it on your device with your positions: nobody knows what you hold.'],
      steps: ['Import the M1 Holdings CSV to see news about your positions; tap a symbol to see only its news.', 'Open a story; when you come back, answer "Yes, relevant" or "Not for me". "For you" sorts by what matters to you; "Latest", by time.', 'Switch tabs with the buttons or the 1–6 keys; "/" searches and "R" refreshes.', 'Tap a topic (Economy, Politics…) to see only those stories.', 'In "Countries" pick the ones you care about; they are remembered.', 'A headline\'s × hides that source; bring it back in "Source status".'] } },

  /* ---------- Alquiler ---------- */
  rental: {
    es: { t: 'Casa en alquiler', d: ['Rentabilidad mensual con las cifras que configuras: renta menos hipoteca, HOA, impuestos, seguro, mantenimiento y otros gastos. También el valor neto que tienes en la casa.', 'Si importas movimientos con las categorías "Renta alquiler", "HOA alquiler" o "Gastos alquiler", ves lo cobrado y pagado de verdad cada mes.'], steps: ['Pulsa <b>Editar</b> y rellena renta, HOA, impuestos anuales, seguro, mantenimiento y, para impuestos, el valor de la construcción y el año en que empezaste a alquilar.', 'Registra las reparaciones con "+ Registrar gasto extra".', 'Actualiza el valor de la casa de vez en cuando.'] },
    en: { t: 'Rental property', d: ['Monthly return with the figures you set: rent minus mortgage, HOA, taxes, insurance, maintenance and other costs. Also the equity you have in the house.', 'If you import transactions with the categories "Rental income", "Rental HOA" or "Rental expenses", you see what was actually collected and paid each month.'], steps: ['Tap <b>Edit</b> and fill in rent, HOA, annual taxes, insurance, maintenance and, for taxes, the building value and the year you started renting.', 'Record repairs with "+ Record an extra cost".', 'Update the house value now and then.'] } },

  /* ---------- Cuentas ---------- */
  accounts: {
    es: { t: 'Cuentas', d: ['Todas tus cuentas agrupadas por tipo: bancos, tarjetas, inversión, jubilación, ahorro de los hijos, inmuebles, hipotecas y otros activos. Cada una guarda un historial de saldos.', 'Aquí también se importan los extractos: en la pestaña <b>Extractos</b> (qué falta este mes y muchos archivos a la vez), con el botón <b>+</b>, con el botón <b>Importar</b> de cada cuenta o compartiendo el PDF desde la app del banco. Junto al saldo verás "Falta oct" si falta el extracto de ese mes.'], steps: ['Toca una cuenta para ver su ficha: saldo, últimos movimientos y los botones Importar, Actualizar saldo, Editar e Historial.', '"Añadir cuenta" empieza por un extracto: la app crea la cuenta a partir del documento. "Crear sin documento" es para una casa, efectivo o cuentas sin extractos.', '"Importar" en la ficha de una cuenta: los archivos que elijas se guardan en ella (salvo que sus últimos 4 dígitos sean de otra cuenta).', '"Editar → Borrar" elimina la cuenta y todo lo que vino de ella (movimientos, saldos, posiciones, aportaciones, documentos fiscales vinculados y su registro de extractos), como si nunca la hubieras importado.', '"Actualizar saldo" añade el saldo de una fecha; "Historial" muestra y borra saldos antiguos; "Editar" cambia el nombre, los 4 últimos dígitos y los datos de hipotecas e inmuebles.', 'Los inmuebles llevan su valor de mercado estimado; las hipotecas, lo que debes.'] },
    en: { t: 'Accounts', d: ['All your accounts grouped by type: banks, cards, brokerage, retirement, kids savings, property, mortgages and other assets. Each keeps a balance history.', 'Statements are imported here too: in the <b>Statements</b> tab (what is missing this month and many files at once), with the <b>+</b> button, with each account\'s <b>Import</b> button or by sharing the PDF from your bank\'s app. Next to the balance you\'ll see "Missing Oct" if that month\'s statement is missing.'], steps: ['Tap an account to open it: balance, latest transactions and the Import, Update balance, Edit and History buttons.', '"Add account" starts from a statement: the app creates the account from the document. "Create without a document" is for a house, cash or accounts without statements.', '"Import" in an account\'s page: the files you choose are saved to it (unless their last 4 digits belong to another account).', '"Edit → Delete" removes the account and everything that came from it (transactions, balances, positions, contributions, linked tax documents and its statement record), as if you had never imported it.', '"Update balance" adds a balance for a date; "History" shows and deletes old balances; "Edit" changes the name, the last 4 digits and the mortgage and property details.', 'Properties hold their estimated market value; mortgages, what you owe.'] } },
  acc_first: {
    es: { t: 'Tu primera cuenta', d: ['Las cuentas se crean a partir de un extracto: así la app sabe desde el principio la entidad, el tipo de cuenta, los últimos 4 dígitos y el saldo, y trae los movimientos.', 'Los archivos se leen dentro del navegador y no salen del dispositivo.'], steps: ['Descarga de la web de tu banco, tarjeta, bróker o hipoteca el último extracto (PDF) o los movimientos (CSV).', 'Elige uno o varios aquí (o compártelos desde la app del banco). La app reconoce cada documento y crea la cuenta; si no reconoce un archivo, abre su revisión con "Cuenta nueva" ya marcada.', 'Comprueba el nombre, el tipo y el saldo y guarda.', 'Una casa, efectivo o algo sin extractos: "Crear sin documento".'] },
    en: { t: 'Your first account', d: ['Accounts are created from a statement: that way the app knows the institution, the account type, the last 4 digits and the balance from the start, and brings in the transactions.', 'Files are read inside the browser and never leave the device.'], steps: ['Download the latest statement (PDF) or the transactions (CSV) from your bank, card, broker or mortgage website.', 'Choose one or several here (or share them from your bank\'s app). The app recognizes each document and creates the account; if it doesn\'t recognize a file, it opens its review with "New account" already selected.', 'Check the name, the type and the balance, and save.', 'A house, cash or something without statements: "Create without a document".'] } },

  /* ---------- Importar ---------- */
  stmt_routine: {
    es: { t: 'Extractos del mes', d: ['Tu rutina mensual en dos minutos: la lista dice qué cuentas están al día y de cuáles falta el extracto (por ejemplo, "Falta el de octubre"). La app lo calcula con la fecha del último extracto de cada cuenta y su ritmo: mensual, o trimestral en el 401(k). Si hay huecos en el último año, también los dice.', 'Elige todos los extractos de una vez, PDF y CSV mezclados: la app reconoce cada documento, lo guarda en su cuenta y crea las que falten. Si un solo archivo no lo reconoce, se abre su revisión.', '<b>En Android</b>, con MyFinZen instalada desde Chrome, abre el PDF en la app de tu banco y pulsa <b>Compartir → MyFinZen</b>. <b>En el ordenador</b>, arrastra los archivos a cualquier parte de la app o ábrelos con MyFinZen. Los archivos solo se leen en este dispositivo y, hasta que desbloqueas la app, se quedan en memoria.'], steps: ['Una vez al mes, descarga los extractos nuevos de cada banco, tarjeta, inversión e hipoteca.', 'Compártelos con MyFinZen, arrástralos o elígelos aquí todos a la vez.', 'El botón Importar de cada fila guarda los archivos en esa cuenta.', '"No necesita" quita del recordatorio una cuenta sin extractos (efectivo, por ejemplo); "Recordar" la vuelve a poner.', 'En el Resumen verás un aviso cuando falte algún extracto.'] },
    en: { t: 'This month\'s statements', d: ['Your monthly routine in two minutes: the list shows which accounts are up to date and which statement is missing (for example, "October is missing"). The app works it out from the date of each account\'s latest statement and its rhythm: monthly, or quarterly for the 401(k). If there are gaps in the last year, it tells you too.', 'Choose all the statements at once, PDFs and CSVs mixed: the app recognizes each document, saves it to its account and creates any missing ones. If it doesn\'t recognize a single file, its review opens.', '<b>On Android</b>, with MyFinZen installed from Chrome, open the PDF in your bank\'s app and tap <b>Share → MyFinZen</b>. <b>On a computer</b>, drag the files anywhere onto the app or open them with MyFinZen. Files are only read on this device and, until you unlock the app, they stay in memory.'], steps: ['Once a month, download the new statements from each bank, card, investment and mortgage.', 'Share them with MyFinZen, drag them in or choose them all here at once.', 'Each row\'s Import button saves the files to that account.', '"Not needed" removes an account without statements (cash, for example) from the reminder; "Remind" puts it back.', 'The Overview shows an alert when a statement is missing.'] } },
  imp_batch: {
    es: { t: 'Importar varios archivos a la vez', d: ['Elige de una vez todos los extractos que hayas descargado, PDF y CSV mezclados. La app los procesa uno detrás de otro y reconoce qué es cada uno: extracto de banco o tarjeta, hipoteca, formulario fiscal o posiciones de M1.', 'Cada archivo se guarda en su cuenta si la app la reconoce con seguridad: por los <b>últimos 4 dígitos</b> de la cuenta, por lo que <b>aprendió</b> la última vez que importaste un archivo parecido, o por la <b>entidad</b> si solo tienes una cuenta en ella. Si el extracto es de una cuenta que aún no existe y se reconoce el banco y el número de cuenta, <b>crea la cuenta sola</b> (verás «cuenta nueva»). Los que no sabe asignar quedan marcados para revisar. Los movimientos que ya estaban se ignoran. La app <b>recuerda cada extracto importado</b> (por el archivo y por su contenido: cuenta, fecha, saldo y movimientos), así que si vuelves a subir uno, aunque sea otro día o con otro nombre, lo salta sin sumar nada. Con "Importar de nuevo" lo reemplaza sin duplicar.', 'Los extractos de Bank of America (cuentas y tarjetas), M1, Empower (con sus fondos), Wells Fargo y Pennymac se leen con lectores específicos: saldo, fecha, número de cuenta y movimientos.', 'Después, la app <b>comprueba</b> que lo leído cuadra con el propio extracto (saldo inicial + movimientos = saldo final; fondos = total) y lo indica con ✓ o ⚠ en el resumen.'],
      steps: ['Pon los 4 últimos dígitos en cada cuenta (Cuentas → Editar): es la forma más segura de que cada extracto vaya a su sitio.', 'Pulsa "Elegir archivos" y selecciona todos (o arrástralos).', 'Mira el resumen: ✓ guardado, ! para revisar, i sin cambios.', 'Pulsa "Revisar" en los marcados: se abre la revisión de siempre debajo. La próxima vez, ese archivo ya irá solo a su cuenta.', 'Después, revisa la conciliación en Movimientos.'] },
    en: { t: 'Import several files at once', d: ['Choose all the statements you downloaded at once, PDFs and CSVs mixed. The app processes them one after another and recognizes each one: bank or card statement, mortgage, tax form or M1 positions.', 'Each file is saved to its account if the app recognizes it with certainty: by the account\'s <b>last 4 digits</b>, by what it <b>learned</b> the last time you imported a similar file, or by the <b>institution</b> if you only have one account there. If the statement belongs to an account that doesn\'t exist yet and the bank and account number are recognized, it <b>creates the account itself</b> (you\'ll see “new account”). Files it can\'t assign are marked for review. Transactions already saved are skipped. The app <b>remembers every imported statement</b> (by the file and by its content: account, date, balance and transactions), so if you upload one again, even on another day or with another name, it skips it without adding anything. "Import again" replaces it without duplicating.', 'Statements from Bank of America (accounts and cards), M1, Empower (with its funds), Wells Fargo and Pennymac are read with specific readers: balance, date, account number and transactions.', 'Then the app <b>checks</b> that what it read matches the statement itself (opening balance + transactions = closing balance; funds = total) and shows ✓ or ⚠ in the summary.'],
      steps: ['Set the last 4 digits on each account (Accounts → Edit): it is the surest way for each statement to land in the right place.', 'Tap "Choose files" and select them all (or drag them in).', 'Check the summary: ✓ saved, ! to review, i unchanged.', 'Tap "Review" on the marked ones: the usual review opens below. Next time, that file will go to its account on its own.', 'Then check the reconciliation in Transactions.'] } },
  imp_csv: {
    es: { t: 'Importar CSV', d: ['La forma más fiable de traer movimientos: casi todos los bancos y tarjetas permiten descargar un CSV desde su web. Los duplicados se ignoran.', 'También reconoce el CSV de Holdings de M1 (posiciones).'], steps: ['Descarga el CSV del periodo que quieras desde la web de tu banco o tarjeta.', 'Elígelo aquí. Comprueba que las columnas de fecha, descripción e importe son las correctas.', 'Los gastos deben salir en negativo: si salen en positivo (típico en tarjetas), marca "Invertir signo".', 'Elige la cuenta o crea una nueva y pulsa Importar. Después, revisa la conciliación.'] },
    en: { t: 'Import CSV', d: ['The most reliable way to bring in transactions: almost every bank and card lets you download a CSV from its website. Duplicates are skipped.', 'It also recognizes the M1 Holdings CSV (positions).'], steps: ['Download the CSV for the period you want from your bank or card website.', 'Choose it here. Check that the date, description and amount columns are right.', 'Expenses must be negative: if they come out positive (common for cards), check "Flip sign".', 'Choose the account or create a new one and tap Import. Then review the reconciliation.'] } },
  imp_pdf: {
    es: { t: 'Importar PDF', d: ['Lee extractos de banco, tarjeta, inversión, jubilación e hipoteca, y formularios fiscales (W-2, 1098, 1099, 5498, impuesto de propiedad). Todo se lee en tu dispositivo.', 'Si algo no se reconoce, "Leer con Claude" envía solo el texto con tus datos personales ocultos (necesita tu clave de API).'], steps: ['Elige uno o varios PDFs: se procesan uno detrás de otro.', 'Revisa el saldo, la fecha y los movimientos detectados antes de guardar.', 'Los formularios fiscales se guardan en <b>Impuestos</b>; las hipotecas, en <b>Hipotecas</b>.'] },
    en: { t: 'Import PDF', d: ['Reads bank, card, brokerage, retirement and mortgage statements, and tax forms (W-2, 1098, 1099, 5498, property tax). Everything is read on your device.', 'If something isn\'t recognized, "Read with Claude" sends only the text with your personal data hidden (needs your API key).'], steps: ['Choose one or more PDFs: they are processed one after another.', 'Check the detected balance, date and transactions before saving.', 'Tax forms are saved in <b>Taxes</b>; mortgages, in <b>Mortgages</b>.'] } },
  imp_paste: {
    es: { t: 'Pegar CSV como texto', d: ['Para cuando no puedes elegir el archivo (por ejemplo, dentro de otra app que no deja abrir archivos).'], steps: ['Abre el CSV en el móvil, selecciona todo y cópialo.', 'Pégalo aquí, ponle un nombre si quieres y pulsa "Importar texto".'] },
    en: { t: 'Paste CSV as text', d: ['For when you can\'t pick the file (for example, inside another app that doesn\'t allow opening files).'], steps: ['Open the CSV on your phone, select everything and copy it.', 'Paste it here, give it a name if you like and tap "Import text".'] } },

  /* ---------- Impuestos ---------- */
  taxes: {
    es: { t: 'Impuestos', d: ['Estimación de tu declaración federal y de California, los documentos que necesitas, recomendaciones para pagar menos de forma legal y una guía paso a paso para TurboTax con tus cifras.', 'Es una estimación orientativa: no sustituye a un CPA o enrolled agent.'], steps: ['Elige el año arriba a la derecha.', 'Rellena <b>Familia y situación</b> una vez al año.', 'Importa los formularios (W-2, 1098, 1099…) cuando lleguen en enero y febrero.', 'Revisa <b>Cómo pagar menos</b> antes del 31 de diciembre y sigue la <b>Guía TurboTax</b> al declarar.'] },
    en: { t: 'Taxes', d: ['An estimate of your federal and California return, the documents you need, recommendations to legally pay less and a step-by-step TurboTax guide with your figures.', 'It is an estimate for guidance: it doesn\'t replace a CPA or enrolled agent.'], steps: ['Choose the year at the top right.', 'Fill in <b>Family & situation</b> once a year.', 'Import the forms (W-2, 1098, 1099…) when they arrive in January and February.', 'Review <b>How to pay less</b> before December 31 and follow the <b>TurboTax guide</b> when filing.'] } },
  tax_agi: {
    es: { t: 'Cifras clave del año', d: ['AGI (ingreso bruto ajustado), deducción federal (estándar o detallada, la que te conviene), impuesto estimado y devolución o pago, con los documentos registrados y tu perfil.'], steps: ['Las cifras se afinan a medida que importas documentos.', 'Hasta que llegue el W-2, usa el salario estimado de <b>Familia y situación</b>.'] },
    en: { t: 'Key figures for the year', d: ['AGI (adjusted gross income), federal deduction (standard or itemized, whichever is better), estimated tax and refund or amount due, with the recorded documents and your profile.'], steps: ['The figures get sharper as you import documents.', 'Until the W-2 arrives, use the estimated wages in <b>Family & situation</b>.'] } },
  tax_docs: {
    es: { t: 'Documentos que necesitas', d: ['Lista creada a partir de tus cuentas: W-2, 1098 de cada hipoteca, 1099 de bancos e inversiones, recibos del impuesto de propiedad, etc. Se marcan solos al importarlos.'], steps: ['Importa cada PDF en <b>Cuentas → Importar</b> según vaya llegando.', 'Los opcionales (en azul) solo hacen falta si aplican.'] },
    en: { t: 'Documents you need', d: ['A list built from your accounts: W-2, a 1098 for each mortgage, 1099s from banks and brokers, property tax bills, etc. They tick themselves off when imported.'], steps: ['Import each PDF in <b>Accounts → Import</b> as it arrives.', 'The optional ones (in blue) are only needed if they apply.'] } },
  tax_year: {
    es: { t: 'Tus datos del año', d: ['Forma de declarar, hijos, donativos, otros ingresos y pagos estimados. Lo que no venga en un formulario se pone aquí.'], steps: ['Rellénalo y pulsa Guardar.', 'Con "+ Documento a mano" añades un formulario sin PDF.'] },
    en: { t: 'Your data for the year', d: ['Filing status, children, donations, other income and estimated payments. Anything not on a form goes here.'], steps: ['Fill it in and tap Save.', 'With "+ Document by hand" you add a form without a PDF.'] } },
  tax_fed: {
    es: { t: 'Cálculo federal', d: ['El cálculo línea a línea: salarios, intereses, dividendos, ganancias, alquiler (Schedule E), deducciones, base imponible, impuesto, créditos y lo ya pagado.'], steps: ['Compara estas cifras con las de TurboTax cuando declares: si difieren mucho, suele faltar un documento.'] },
    en: { t: 'Federal calculation', d: ['The line-by-line calculation: wages, interest, dividends, gains, rental (Schedule E), deductions, taxable income, tax, credits and what was already paid.'], steps: ['Compare these figures with TurboTax when you file: if they differ a lot, a document is usually missing.'] } },
  tax_item: {
    es: { t: '¿Estándar o detallada?', d: ['Compara la deducción estándar con la detallada (intereses de hipoteca, impuestos estatales y locales con su tope SALT, donativos) en la federal y en California, que tiene reglas distintas.'], steps: ['La app elige automáticamente la que más te conviene en cada una.'] },
    en: { t: 'Standard or itemized?', d: ['Compares the standard deduction with itemizing (mortgage interest, state and local taxes with the SALT cap, donations) for federal and for California, which has different rules.'], steps: ['The app automatically picks the better one for each.'] } },
  tax_sche: {
    es: { t: 'Schedule E (alquiler)', d: ['Ingresos y gastos de la casa alquilada para la declaración: rentas, intereses de hipoteca, impuesto de propiedad, seguro, HOA, reparaciones y amortización.'], steps: ['Si falta la amortización, añade el valor de la construcción y el año de inicio en <b>Cuentas → Editar la casa</b>.', 'Con "Ajustar cifras" corriges cualquier importe.'] },
    en: { t: 'Schedule E (rental)', d: ['Income and expenses of the rental for the return: rents, mortgage interest, property tax, insurance, HOA, repairs and depreciation.'], steps: ['If depreciation is missing, add the building value and start year in <b>Accounts → Edit the house</b>.', 'With "Adjust figures" you correct any amount.'] } },
  tax_prep: {
    es: { t: 'Preparar la declaración', d: ['Pide a Claude una revisión de tus datos fiscales (con tu clave de API) o copia un resumen para tu preparador o para tenerlo a mano en TurboTax.'], steps: ['"Resumen para el preparador" se puede copiar o descargar como texto.'] },
    en: { t: 'Prepare the return', d: ['Ask Claude to review your tax data (with your API key) or copy a summary for your preparer or to keep at hand in TurboTax.'], steps: ['"Summary for the preparer" can be copied or downloaded as text.'] } },
  prof_home: {
    es: { t: 'Hogar', d: ['Forma de declarar, tu edad, si tu cónyuge trabaja y si tenéis plan de jubilación en el trabajo. Decide qué IRA puede deducirse y otros límites.'], steps: ['Rellénalo una vez al año y pulsa "Guardar perfil".'] },
    en: { t: 'Household', d: ['Filing status, your age, whether your spouse works and whether you have a retirement plan at work. It decides which IRA can be deducted and other limits.'], steps: ['Fill it in once a year and tap "Save profile".'] } },
  prof_kids: {
    es: { t: 'Hijos', d: ['El año de nacimiento de cada hijo determina el crédito por hijos, los gastos de guardería y la Trump Account ($1,000 para los nacidos entre 2025 y 2028).'], steps: ['Añade cada hijo con su año, si tiene SSN y si vive con vosotros.', 'Marca el Form 4547 cuando lo hayas presentado.'] },
    en: { t: 'Children', d: ['Each child\'s birth year determines the child tax credit, child care costs and the Trump Account ($1,000 for those born 2025–2028).'], steps: ['Add each child with the year, whether they have an SSN and whether they live with you.', 'Check Form 4547 once you have filed it.'] } },
  prof_pay: {
    es: { t: 'Sueldo del año', d: ['Hasta que llegue el W-2, estas cifras estiman tu año completo: salario, 401(k), retenciones y CA SDI.'], steps: ['Usa la última nómina: lo acumulado del año y una estimación hasta diciembre.'] },
    en: { t: 'Pay for the year', d: ['Until the W-2 arrives, these figures estimate your full year: wages, 401(k), withholding and CA SDI.'], steps: ['Use your latest pay stub: the year-to-date amounts plus an estimate through December.'] } },
  prof_save: {
    es: { t: 'Salud, guardería y ahorro', d: ['HSA, Dependent Care FSA, IRA, Roth, 529 e impuesto de propiedad de tu casa. Sirven para calcular deducciones y recomendaciones.'], steps: ['Pon lo aportado en el año; si no sabes algo, déjalo en "No sé".'] },
    en: { t: 'Health, child care and savings', d: ['HSA, Dependent Care FSA, IRA, Roth, 529 and your home\'s property tax. They are used to calculate deductions and recommendations.'], steps: ['Enter what you contributed in the year; if you don\'t know something, leave "Don\'t know".'] } },
  opt_total: {
    es: { t: 'Ahorro posible', d: ['Suma aproximada (federal + California) de lo que ahorrarías haciendo las recomendaciones de abajo que reducen impuestos.'], steps: ['Empieza por las de arriba: están ordenadas de más a menos ahorro.'] },
    en: { t: 'Possible savings', d: ['Approximate sum (federal + California) of what you would save by doing the tax-reducing recommendations below.'], steps: ['Start at the top: they are ordered from most to least savings.'] } },
  opt_recs: {
    es: { t: 'Recomendaciones', d: ['Acciones legales para pagar menos, calculadas con tus cifras: 401(k), IRA del cónyuge, HSA, guardería, Trump Account, impuesto de propiedad, donativos, alquiler, tax-loss harvesting, retenciones y más. Cada una indica cuándo hacerla y dónde va en TurboTax.'], steps: ['Revísalas antes del 31 de diciembre: muchas solo valen dentro del año.', 'Confirma las decisiones importantes con un profesional.'] },
    en: { t: 'Recommendations', d: ['Legal actions to pay less, calculated with your figures: 401(k), spousal IRA, HSA, child care, Trump Account, property tax, donations, rental, tax-loss harvesting, withholding and more. Each says when to do it and where it goes in TurboTax.'], steps: ['Review them before December 31: many only count within the year.', 'Confirm important decisions with a professional.'] } },
  opt_ai: {
    es: { t: 'Plan con Claude', d: ['Claude revisa las recomendaciones y tu perfil (solo edades y cifras, sin nombres ni números de cuenta) y propone un plan completo.'], steps: ['Necesita tu clave de API en <b>Copia y ajustes</b>.'] },
    en: { t: 'Plan with Claude', d: ['Claude reviews the recommendations and your profile (ages and figures only, no names or account numbers) and proposes a full plan.'], steps: ['It needs your API key in <b>Backup & settings</b>.'] } },
  turbo: {
    es: { t: 'Guía TurboTax', d: ['Los pasos para presentar tu declaración en TurboTax con los valores que tienes que introducir en cada pantalla. Los nombres de menú están en inglés, como aparecen en TurboTax.'], steps: ['Marca cada paso al terminarlo.', 'Si TurboTax ha cambiado el nombre de un menú, búscalo con la lupa.', 'Con "Copiar la guía" la tienes en texto.'] },
    en: { t: 'TurboTax guide', d: ['The steps to file your return in TurboTax with the values to enter on each screen.'], steps: ['Tick each step when you finish it.', 'If TurboTax renamed a menu, search for it.', 'With "Copy the guide" you get it as text.'] } },

  /* ---------- Claude ---------- */
  claude: {
    es: { t: 'Pregunta a Claude', d: ['Análisis con IA usando solo un resumen de cifras (saldos, totales por categoría, hipotecas). Nunca se envían tus extractos, movimientos individuales ni números de cuenta.', 'Necesita tu clave de API de Anthropic; se paga por uso (unos céntimos por pregunta).'], steps: ['Elige una de las preguntas rápidas o escribe la tuya.', 'En "Ver exactamente lo que se envía" ves los datos.'] },
    en: { t: 'Ask Claude', d: ['AI analysis using only a summary of figures (balances, totals by category, mortgages). Your statements, individual transactions and account numbers are never sent.', 'It needs your Anthropic API key; you pay per use (a few cents per question).'], steps: ['Pick one of the quick questions or type your own.', '"See exactly what is sent" shows the data.'] } },

  /* ---------- Ajustes ---------- */
  sync: {
    es: { t: 'Tus dispositivos', d: ['Usa MyFinZen en el móvil, la tableta y el ordenador con los mismos datos. Se guarda en tu nube un archivo cifrado con tu contraseña maestra (el mismo cifrado que en este dispositivo): la nube no puede leerlo.', 'Si cambias algo en dos dispositivos a la vez, se juntan los cambios registro a registro; solo si los dos cambian lo mismo gana el último. La clave de API de Claude y la conexión con la nube son de cada dispositivo y no se sincronizan.', 'Formas: Dropbox (automático en todos tus dispositivos), un archivo en tu carpeta de OneDrive, Google Drive, iCloud Drive o Dropbox del ordenador (automático en ese ordenador) o a mano en el móvil (subes el archivo a tu nube y lo abres desde el otro dispositivo).', 'Como el archivo está en la nube, usa una contraseña maestra larga: es lo único que lo protege.'], steps: ['Aquí, elige cómo sincronizar.', 'En el otro dispositivo, abre MyFinZen y toca «Ya uso MyFinZen en otro dispositivo».', 'Elige la misma nube o abre el archivo y desbloquea con tu contraseña maestra.', 'La nube de arriba indica el estado: toca para sincronizar en ese momento.'] },
    en: { t: 'Your devices', d: ['Use MyFinZen on your phone, tablet and computer with the same data. An encrypted file is saved in your cloud with your master password (the same encryption as on this device): the cloud can\'t read it.', 'If you change things on two devices at once, the changes are combined record by record; only if both change the same thing does the latest win. The Claude API key and the cloud connection belong to each device and aren\'t synced.', 'Ways: Dropbox (automatic on all your devices), a file in your computer\'s OneDrive, Google Drive, iCloud Drive or Dropbox folder (automatic on that computer) or by hand on your phone (you upload the file to your cloud and open it from the other device).', 'Since the file is in the cloud, use a long master password: it is the only thing protecting it.'], steps: ['Here, choose how to sync.', 'On the other device, open MyFinZen and tap "I already use MyFinZen on another device".', 'Choose the same cloud or open the file, and unlock with your master password.', 'The cloud icon at the top shows the status: tap it to sync right away.'] } },
  payshift: {
    es: { t: 'Tu nómina', d: ['Si cobras a final de mes (por ejemplo el día 25) y ese dinero es el que gastas el mes siguiente, activa esta opción: la nómina cobrada desde el día que elijas cuenta como ingreso del mes siguiente.', 'Así el ahorro del mes compara lo que cobraste para ese mes con lo que llevas gastado, en vez de salir siempre negativo hasta que llega la nómina. En Movimientos verás "incl. nómina del 25 oct" debajo de los ingresos.', 'Solo cambia el cálculo de ingresos, gastos y ahorro por mes. La lista de movimientos y los impuestos siguen usando la fecha real.'], steps: ['Marca la casilla.', 'Elige el día desde el que la nómina cuenta para el mes siguiente (el día en que sueles cobrar o uno antes).', 'Comprueba el ahorro del mes en Movimientos.'] },
    en: { t: 'Your paycheck', d: ['If you get paid at the end of the month (for example on the 25th) and that is the money you spend the next month, turn this on: paychecks received from the day you choose count as income for the following month.', 'That way the month\'s savings compare what you earned for that month with what you have spent so far, instead of always being negative until the paycheck arrives. In Transactions you will see "incl. paycheck of Oct 25" under income.', 'It only changes the income, expenses and savings per month. The transaction list and taxes keep using the real date.'], steps: ['Tick the box.', 'Choose the day from which the paycheck counts for the next month (the day you usually get paid, or one before).', 'Check the month\'s savings in Transactions.'] } },
  lang: {
    es: { t: 'Idioma', d: ['Cambia el idioma de toda la aplicación entre español e inglés. Tus datos no cambian.'], steps: ['Elige el idioma en el desplegable. También puedes cambiarlo en la pantalla de desbloqueo.'] },
    en: { t: 'Language', d: ['Switches the whole app between Spanish and English. Your data doesn\'t change.'], steps: ['Choose the language in the dropdown. You can also change it on the unlock screen.'] } },
  backup: {
    es: { t: 'Copia de seguridad', d: ['Tus datos solo existen en este dispositivo. Una copia cifrada con contraseña te protege si se borra el navegador o pierdes el móvil, y sirve para pasar los datos a otro dispositivo.'], steps: ['Escribe una contraseña para la copia de al menos 10 caracteres (mejor una frase; no tiene por qué ser la maestra) y pulsa "Crear copia cifrada".', 'Guarda el archivo en Dropbox, Google Drive o donde quieras: sin la contraseña nadie puede leerlo.', 'Hazlo al menos una vez al mes; la app te avisa si pasan más de 30 días.'] },
    en: { t: 'Backup', d: ['Your data only exists on this device. A password-encrypted backup protects you if the browser is cleared or you lose your phone, and lets you move the data to another device.'], steps: ['Type a backup password of at least 10 characters (a phrase is best; it doesn\'t have to be the master one) and tap "Create encrypted backup".', 'Keep the file in Dropbox, Google Drive or wherever you like: without the password nobody can read it.', 'Do it at least once a month; the app warns you after 30 days.'] } },
  restore: {
    es: { t: 'Restaurar copia', d: ['Sustituye todos los datos de este dispositivo por los de una copia. La clave de API de Claude de este dispositivo se mantiene.'], steps: ['Elige el archivo .json (o pega su texto) y escribe la contraseña de la copia.', 'Confirma: verás cuántas cuentas y movimientos tiene antes de sustituir nada.'] },
    en: { t: 'Restore backup', d: ['Replaces all the data on this device with a backup\'s. This device\'s Claude API key is kept.'], steps: ['Choose the .json file (or paste its text) and type the backup password.', 'Confirm: you\'ll see how many accounts and transactions it has before anything is replaced.'] } },
  prefs: {
    es: { t: 'Preferencias', d: ['Meses de gastos que quieres en el fondo de emergencia, contexto para Claude, nombres que se ocultan antes de enviar texto a Claude y si quieres que lea automáticamente los PDF no reconocidos.'], steps: ['Cambia lo que quieras y pulsa Guardar.'] },
    en: { t: 'Preferences', d: ['Months of expenses you want in the emergency fund, context for Claude, names hidden before sending text to Claude, and whether unrecognized PDFs are read automatically.'], steps: ['Change what you like and tap Save.'] } },
  rules: {
    es: { t: 'Categorías y reglas', d: ['Las reglas asignan la categoría según el texto del movimiento. Se crean solas cuando recategorizas un movimiento y aceptas aplicarlo a todos.'], steps: ['"Gestionar categorías" abre tus categorías propias.', 'La ✕ borra una regla.', '"Volver a categorizar todo" aplica las reglas a los movimientos existentes (no toca los que cambiaste a mano).'] },
    en: { t: 'Categories and rules', d: ['Rules assign the category from the transaction text. They are created automatically when you recategorize a transaction and choose to apply it to all.'], steps: ['"Manage categories" opens your custom categories.', 'The ✕ deletes a rule.', '"Recategorize everything" applies the rules to existing transactions (it doesn\'t touch the ones you changed by hand).'] } },
  security: {
    es: { t: 'Seguridad', d: ['La app se bloquea sola tras unos minutos sin usarla. Aquí gestionas las passkeys (huella, cara o PIN), cambias la contraseña maestra y generas una clave de recuperación nueva.', 'Clave secreta de la bóveda: si sincronizas con la nube, actívala. Es una clave aleatoria que solo está en tus dispositivos (nunca se sube) y que, junto con la contraseña, protege el archivo de la nube: quien lo consiga no puede ni intentar adivinar la contraseña. Cada dispositivo nuevo la pide una vez (escanea el código o escríbela). La huella y la clave de recuperación no la necesitan.'], steps: ['Elige el tiempo de bloqueo.', 'Añade una passkey en cada dispositivo que uses.', 'Si sincronizas, activa la clave secreta y guárdala con tu clave de recuperación.', 'Si generas una clave de recuperación nueva, la anterior deja de funcionar: apúntala en papel.'] },
    en: { t: 'Security', d: ['The app locks itself after a few idle minutes. Here you manage passkeys (fingerprint, face or PIN), change the master password and generate a new recovery key.', 'Vault secret key: if you sync with the cloud, turn it on. It is a random key that is only on your devices (never uploaded) and, together with the password, protects the cloud file: whoever gets it can\'t even try to guess the password. Each new device asks for it once (scan the code or type it). Your fingerprint and the recovery key don\'t need it.'], steps: ['Choose the lock time.', 'Add a passkey on each device you use.', 'If you sync, turn on the secret key and keep it with your recovery key.', 'If you generate a new recovery key, the old one stops working: write it on paper.'] } },
  apikey: {
    es: { t: 'Clave de API de Claude', d: ['Opcional. Activa el análisis con IA, el plan de impuestos y la lectura de PDF difíciles. Se guarda cifrada y no va en las copias.'], steps: ['Créala en console.anthropic.com → API Keys.', 'Pégala, pulsa "Guardar clave" y luego "Probar".'] },
    en: { t: 'Claude API key', d: ['Optional. Turns on AI analysis, the tax plan and reading difficult PDFs. It is stored encrypted and is not included in backups.'], steps: ['Create it at console.anthropic.com → API Keys.', 'Paste it, tap "Save key" and then "Test".'] } },
  wipe: {
    es: { t: 'Borrar todo', d: ['Elimina los datos, la contraseña y las passkeys de este dispositivo. No se puede deshacer.'], steps: ['Haz antes una copia cifrada si quieres conservar algo.'] },
    en: { t: 'Delete everything', d: ['Removes the data, password and passkeys from this device. It cannot be undone.'], steps: ['Make an encrypted backup first if you want to keep anything.'] } }
};

